// Times sets number of times TaskRepo.UpsertUser should be invoked
func (mmUpsertUser *mTaskRepoMockUpsertUser) Times(n uint64) *mTaskRepoMockUpsertUser {
	if n == 0 {
		mmUpsertUser.mock.t.Fatalf("Times of TaskRepoMock.UpsertUser mock can not be zero")
	}
	mm_atomic.StoreUint64(&mmUpsertUser.expectedInvocations, n)
	mmUpsertUser.expectedInvocationsOrigin = minimock.CallerInfo(1)
	return mmUpsertUser
}

func (mmUpsertUser *mTaskRepoMockUpsertUser) invocationsDone() bool {
	if len(mmUpsertUser.expectations) == 0 && mmUpsertUser.defaultExpectation == nil && mmUpsertUser.mock.funcUpsertUser == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmUpsertUser.mock.afterUpsertUserCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmUpsertUser.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// UpsertUser implements mm_service.TaskRepo
func (mmUpsertUser *TaskRepoMock) UpsertUser(ctx context.Context, userID string, driverType string) (err error) {
	mm_atomic.AddUint64(&mmUpsertUser.beforeUpsertUserCounter, 1)
	defer mm_atomic.AddUint64(&mmUpsertUser.afterUpsertUserCounter, 1)

	mmUpsertUser.t.Helper()

	if mmUpsertUser.inspectFuncUpsertUser != nil {
		mmUpsertUser.inspectFuncUpsertUser(ctx, userID, driverType)
	}

	mm_params := TaskRepoMockUpsertUserParams{ctx, userID, driverType}

	// Record call args
	mmUpsertUser.UpsertUserMock.mutex.Lock()
	mmUpsertUser.UpsertUserMock.callArgs = append(mmUpsertUser.UpsertUserMock.callArgs, &mm_params)
	mmUpsertUser.UpsertUserMock.mutex.Unlock()

	for _, e := range mmUpsertUser.UpsertUserMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.err
		}
	}

	if mmUpsertUser.UpsertUserMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmUpsertUser.UpsertUserMock.defaultExpectation.Counter, 1)
		mm_want := mmUpsertUser.UpsertUserMock.defaultExpectation.params
		mm_want_ptrs := mmUpsertUser.UpsertUserMock.defaultExpectation.paramPtrs

		mm_got := TaskRepoMockUpsertUserParams{ctx, userID, driverType}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmUpsertUser.t.Errorf("TaskRepoMock.UpsertUser got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpsertUser.UpsertUserMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.userID != nil && !minimock.Equal(*mm_want_ptrs.userID, mm_got.userID) {
				mmUpsertUser.t.Errorf("TaskRepoMock.UpsertUser got unexpected parameter userID, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpsertUser.UpsertUserMock.defaultExpectation.expectationOrigins.originUserID, *mm_want_ptrs.userID, mm_got.userID, minimock.Diff(*mm_want_ptrs.userID, mm_got.userID))
			}

			if mm_want_ptrs.driverType != nil && !minimock.Equal(*mm_want_ptrs.driverType, mm_got.driverType) {
				mmUpsertUser.t.Errorf("TaskRepoMock.UpsertUser got unexpected parameter driverType, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpsertUser.UpsertUserMock.defaultExpectation.expectationOrigins.originDriverType, *mm_want_ptrs.driverType, mm_got.driverType, minimock.Diff(*mm_want_ptrs.driverType, mm_got.driverType))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmUpsertUser.t.Errorf("TaskRepoMock.UpsertUser got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmUpsertUser.UpsertUserMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmUpsertUser.UpsertUserMock.defaultExpectation.results
		if mm_results == nil {
			mmUpsertUser.t.Fatal("No results are set for the TaskRepoMock.UpsertUser")
		}
		return (*mm_results).err
	}
	if mmUpsertUser.funcUpsertUser != nil {
		return mmUpsertUser.funcUpsertUser(ctx, userID, driverType)
	}
	mmUpsertUser.t.Fatalf("Unexpected call to TaskRepoMock.UpsertUser. %v %v %v", ctx, userID, driverType)
	return
}

// UpsertUserAfterCounter returns a count of finished TaskRepoMock.UpsertUser invocations
func (mmUpsertUser *TaskRepoMock) UpsertUserAfterCounter() uint64 {
	return mm_atomic.LoadUint64(&mmUpsertUser.afterUpsertUserCounter)
}

// UpsertUserBeforeCounter returns a count of TaskRepoMock.UpsertUser invocations
func (mmUpsertUser *TaskRepoMock) UpsertUserBeforeCounter() uint64 {
	return mm_atomic.LoadUint64(&mmUpsertUser.beforeUpsertUserCounter)
}

// Calls returns a list of arguments used in each call to TaskRepoMock.UpsertUser.
// The list is in the same order as the calls were made (i.e. recent calls have a higher index)
func (mmUpsertUser *mTaskRepoMockUpsertUser) Calls() []*TaskRepoMockUpsertUserParams {
	mmUpsertUser.mutex.RLock()

	argCopy := make([]*TaskRepoMockUpsertUserParams, len(mmUpsertUser.callArgs))
	copy(argCopy, mmUpsertUser.callArgs)

	mmUpsertUser.mutex.RUnlock()

	return argCopy
}

// MinimockUpsertUserDone returns true if the count of the UpsertUser invocations corresponds
// the number of defined expectations
func (m *TaskRepoMock) MinimockUpsertUserDone() bool {
	if m.UpsertUserMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.UpsertUserMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.UpsertUserMock.invocationsDone()
}

// MinimockUpsertUserInspect logs each unmet expectation
func (m *TaskRepoMock) MinimockUpsertUserInspect() {
	for _, e := range m.UpsertUserMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to TaskRepoMock.UpsertUser at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterUpsertUserCounter := mm_atomic.LoadUint64(&m.afterUpsertUserCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.UpsertUserMock.defaultExpectation != nil && afterUpsertUserCounter < 1 {
		if m.UpsertUserMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to TaskRepoMock.UpsertUser at\n%s", m.UpsertUserMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to TaskRepoMock.UpsertUser at\n%s with params: %#v", m.UpsertUserMock.defaultExpectation.expectationOrigins.origin, *m.UpsertUserMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcUpsertUser != nil && afterUpsertUserCounter < 1 {
		m.t.Errorf("Expected call to TaskRepoMock.UpsertUser at\n%s", m.funcUpsertUserOrigin)
	}

	if !m.UpsertUserMock.invocationsDone() && afterUpsertUserCounter > 0 {
		m.t.Errorf("Expected %d calls to TaskRepoMock.UpsertUser at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.UpsertUserMock.expectedInvocations), m.UpsertUserMock.expectedInvocationsOrigin, afterUpsertUserCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *TaskRepoMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockDeleteUserInspect()

			m.MinimockListUserIDsInspect()

			m.MinimockMarkDoneInspect()

			m.MinimockMarkFailedInspect()

			m.MinimockPullPendingTasksInspect()

			m.MinimockSaveTaskInspect()

			m.MinimockUpsertUserInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *TaskRepoMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *TaskRepoMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockDeleteUserDone() &&
		m.MinimockListUserIDsDone() &&
		m.MinimockMarkDoneDone() &&
		m.MinimockMarkFailedDone() &&
		m.MinimockPullPendingTasksDone() &&
		m.MinimockSaveTaskDone() &&
		m.MinimockUpsertUserDone()
}
